std::istringstream in("6\n-3 -1 -4 -1 -5 -9\n");
std::ostringstream out;
std::streambuf* cout_old = std::cout.rdbuf(out.rdbuf());
solve(in, out);
std::cout.rdbuf(cout_old);
CHECK_EQ(out.str(), std::string("-1\n"));

std::istringstream in("8\n10 9 8 8 8 -100 8 8\n");
std::ostringstream out;
std::streambuf* cout_old = std::cout.rdbuf(out.rdbuf());
solve(in, out);
std::cout.rdbuf(cout_old);
CHECK_EQ(out.str(), std::string("43\n"));

